#!/bin/bash
# Spike proof for docs/design/device-segmentation.md (b): default inter-device
# isolation + one one-way service rule, generated by seg-spike from lab.json.
# Everything lives in throw-away network namespaces; the host's own ruleset and
# interfaces are not touched. Run as root: ./netns-isolation.sh ./seg-spike lab.json
set -u
BIN=${1:-./seg-spike}; CFG=${2:-lab.json}
W=$(mktemp -d); trap 'cleanup' EXIT
NS="rtr c_laptop c_cam c_tv c_unk"
cleanup() { for n in $NS; do ip netns pids $n 2>/dev/null | xargs -r kill 2>/dev/null; ip netns del $n 2>/dev/null; done; rm -rf "$W"; }
cleanup 2>/dev/null; W=$(mktemp -d)
pass=0; fail=0
ok()   { echo "  PASS  $*"; pass=$((pass+1)); }
bad()  { echo "  FAIL  $*"; fail=$((fail+1)); }
# expect <ok|deny> <description> <cmd...>
expect() { local want=$1 desc=$2; shift 2
  if "$@" >/dev/null 2>&1; then got=ok; else got=deny; fi
  [ "$got" = "$want" ] && ok "$desc ($want)" || bad "$desc: wanted $want, got $got"; }
X() { ip netns exec "$@"; }
ping4() { X $1 ping -c2 -W2 $2; }
tcp()   { X $1 curl -s -m 2 -o /dev/null http://$2:$3/; }

for n in $NS; do ip netns add $n; done
X rtr sysctl -qw net.ipv4.ip_forward=1 net.ipv6.conf.all.forwarding=1
X rtr ip link add br0 type bridge
X rtr ip link set br0 up
X rtr ip addr add 172.31.77.1/24 dev br0
X rtr ip addr add fd77:31::1/64 dev br0 nodad
# proxy ARP/ND on the bridge: isolated ports cannot see each other, so the router
# answers for every device and forwards (same mechanism hostapd ap_isolate relies on)
X rtr sysctl -qw net.ipv4.conf.br0.proxy_arp=1 net.ipv4.conf.br0.proxy_arp_pvlan=1 net.ipv4.conf.br0.send_redirects=0 net.ipv4.conf.all.send_redirects=0 net.ipv6.conf.br0.proxy_ndp=1
add_client() { # ns name mac last-octet
  local ns=$1 mac=$2 o=$3
  ip link add p_$o netns rtr type veth peer name eth0 netns $ns
  X rtr ip link set p_$o master br0
  X rtr bridge link set dev p_$o isolated on
  X rtr ip link set p_$o up
  X $ns ip link set eth0 address $mac
  X $ns ip link set lo up; X $ns ip link set eth0 up
  X $ns ip addr add 172.31.77.$o/24 dev eth0
  X $ns ip addr add fd77:31::$o/64 dev eth0 nodad
  X $ns ip route add default via 172.31.77.1
  X rtr ip -6 neigh add proxy fd77:31::$o dev br0
}
add_client c_laptop 02:aa:00:00:00:11 11
add_client c_cam    02:aa:00:00:00:12 12
add_client c_tv     02:aa:00:00:00:13 13
add_client c_unk    02:aa:00:00:00:99 99     # never enrolled
# servers: laptop listens on 7000 (to prove cam cannot reach it), cam on 8080/8081, tv on 8080
cat > $W/ka.py <<'EOF'
import http.server,sys
class H(http.server.SimpleHTTPRequestHandler):
    protocol_version = "HTTP/1.1"          # keep-alive: the connection stays open between requests
    def log_message(self,*a): pass
http.server.ThreadingHTTPServer(("0.0.0.0",int(sys.argv[1])),H).serve_forever()
EOF
srv() { (cd $W; exec ip netns exec $1 python3 $W/ka.py $2 >/dev/null 2>&1) & }
srv c_laptop 7000; srv c_cam 8080; srv c_cam 8081; srv c_tv 8080
sleep 1

echo "== 0. baseline: no segmentation rules; the bridge only isolates at layer 2, the router forwards everything"
expect ok "laptop -> cam icmp" ping4 c_laptop 172.31.77.12
expect ok "cam -> laptop tcp 7000" tcp c_cam 172.31.77.11 7000
expect ok "laptop -> cam ipv6 icmp" X c_laptop ping -6 -c3 -W2 fd77:31::12
expect ok "unknown -> cam tcp 8081" tcp c_unk 172.31.77.12 8081

echo "== 1. generate + load rules from $CFG"
$BIN nft $CFG > $W/pseg.nft || { echo "generator failed"; exit 1; }
X rtr nft -c -f $W/pseg.nft && echo "  nft -c (syntax check) OK"
X rtr nft -f $W/pseg.nft || { echo "nft load failed"; exit 1; }
X rtr nft list table inet pseg > $W/loaded.txt

echo "== 2. default deny between devices (laptop=trusted, cam/tv=iot)"
expect deny "laptop -> cam icmp" ping4 c_laptop 172.31.77.12
expect deny "cam -> laptop icmp" ping4 c_cam 172.31.77.11
expect deny "cam -> laptop tcp 7000" tcp c_cam 172.31.77.11 7000
expect deny "laptop -> cam ipv6 icmp" X c_laptop ping -6 -c3 -W2 fd77:31::12
expect deny "laptop -> tv tcp 8080 (service rule names cam only)" tcp c_laptop 172.31.77.13 8080
echo "== 3. group = bidirectional (cam and tv both in iot)"
expect ok "cam -> tv tcp 8080" tcp c_cam 172.31.77.13 8080
expect ok "tv -> cam tcp 8081" tcp c_tv 172.31.77.12 8081
echo "== 4. one-way service rule laptop -> cam tcp/8080"
expect ok "laptop -> cam tcp 8080 (request and reply)" tcp c_laptop 172.31.77.12 8080
expect deny "laptop -> cam tcp 8081 (other port)" tcp c_laptop 172.31.77.12 8081
expect deny "cam -> laptop tcp 7000 (reverse direction is not allowed)" tcp c_cam 172.31.77.11 7000
echo "== 5. identity: unknown MAC, spoofed IP, spoofed MAC"
expect deny "unknown device -> cam tcp 8081" tcp c_unk 172.31.77.12 8081
expect deny "unknown device -> laptop icmp" ping4 c_unk 172.31.77.11
X c_unk ip addr flush dev eth0; X c_unk ip addr add 172.31.77.11/24 dev eth0; X c_unk ip route add default via 172.31.77.1
expect deny "unknown device with the LAPTOP's IP -> cam tcp 8080" tcp c_unk 172.31.77.12 8080
X c_unk ip addr flush dev eth0; X c_unk ip link set eth0 address 02:aa:00:00:00:11; X c_unk ip addr add 172.31.77.99/24 dev eth0; X c_unk ip route add default via 172.31.77.1
expect deny "unknown device with the LAPTOP's MAC (own IP) -> cam tcp 8080" tcp c_unk 172.31.77.12 8080
X c_unk ip link set eth0 address 02:aa:00:00:00:99
# the MAC spoof taught the bridge a stale port for the laptop's MAC: let it relearn
X c_unk ip addr flush dev eth0; X c_unk ip addr add 172.31.77.99/24 dev eth0
X rtr bridge fdb del 02:aa:00:00:00:11 dev p_99 master 2>/dev/null; X rtr ip neigh flush all
X c_laptop ping -c2 -W1 172.31.77.1 >/dev/null 2>&1
echo "== 6. revocation: re-render with cam revoked, reload atomically"
python3 - "$CFG" "$W/revoked.json" <<'EOF'
import json,sys
c=json.load(open(sys.argv[1]))
for d in c["devices"]:
    if d["name"]=="cam": d["revoked"]=True
json.dump(c,open(sys.argv[2],"w"))
EOF
# a long-lived flow laptop -> cam:8080 that is established BEFORE the revocation
cat > $W/longflow.py <<'EOF'
import socket,sys,time
req=b"GET / HTTP/1.1\r\nHost: x\r\nConnection: keep-alive\r\n\r\n"
s=socket.create_connection(("172.31.77.12",8080),timeout=2)
def rt():
    s.sendall(req); s.settimeout(2); buf=b""
    while b"\r\n\r\n" not in buf:                       # read the whole response, headers + Content-Length body
        d=s.recv(65536)
        if not d: return False
        buf+=d
    head,_,body=buf.partition(b"\r\n\r\n")
    n=int([l.split(b":")[1] for l in head.split(b"\r\n") if l.lower().startswith(b"content-length")][0])
    while len(body)<n:
        d=s.recv(65536)
        if not d: return False
        body+=d
    return True
print("request 1 (before revoke):", "answered" if rt() else "closed", flush=True)
time.sleep(1)
print("request 2 (before revoke, same connection):", "answered" if rt() else "closed", flush=True)
time.sleep(float(sys.argv[1]))
try:
    print("request 3 (after revoke, same connection):", "answered" if rt() else "closed by peer")
except Exception as e:
    print("request 3 (after revoke, same connection): no answer,", type(e).__name__)
EOF
X c_laptop python3 $W/longflow.py 4 > $W/longflow.out 2>&1 &
LF=$!
sleep 2
$BIN nft $W/revoked.json > $W/pseg2.nft && X rtr nft -f $W/pseg2.nft && echo "  reloaded without cam"
wait $LF; sed 's/^/    /' $W/longflow.out
grep -q "request 2 (before revoke, same connection): answered" $W/longflow.out && grep -q "request 3 .*no answer" $W/longflow.out && ok "keep-alive flow worked before the revoke and is cut after it" || bad "established flow was not cut (or never worked)"
expect deny "laptop -> cam tcp 8080 after revoke" tcp c_laptop 172.31.77.12 8080
expect deny "tv -> cam tcp 8081 after revoke (group peer)" tcp c_tv 172.31.77.12 8081
expect deny "revoked cam -> tv tcp 8080" tcp c_cam 172.31.77.13 8080
expect deny "laptop -> tv tcp 8080 still denied" tcp c_laptop 172.31.77.13 8080

echo "== counters"
X rtr nft list chain inet pseg seg_forward | grep -E "counter packets [1-9]" | sed 's/^ *//'
echo
echo "RESULT: $pass passed, $fail failed"
cp $W/pseg.nft /tmp/pseg-spike.nft 2>/dev/null; cp $W/loaded.txt /tmp/pseg-spike-loaded.txt 2>/dev/null
kill $(jobs -p) 2>/dev/null
[ $fail -eq 0 ]
